// Using a ReentrantLock as a Mutex
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class MutexExample {
    private static final Lock mutex = new ReentrantLock();

    public static void main(String[] args) {
        Thread t1 = new Thread(MutexExample::criticalSection);
        Thread t2 = new Thread(MutexExample::criticalSection);

        t1.start();
        t2.start();
    }

    private static void criticalSection() {
        mutex.lock();  // Acquiring the mutex
        try {
            System.out.println(Thread.currentThread().getName() + " has the mutex");
            Thread.sleep(1000);  // Simulating work in the critical section
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            mutex.unlock();  // Releasing the mutex
            System.out.println(Thread.currentThread().getName() + " released the mutex");
        }
    }
}

