import java.util.concurrent.Semaphore;

public class SemaphoreExample {
    private static final Semaphore semaphore = new Semaphore(2);  // Allow 2 threads to access the resource at the same time

    public static void main(String[] args) {
        Thread t1 = new Thread(SemaphoreExample::accessResource);
        Thread t2 = new Thread(SemaphoreExample::accessResource);
        Thread t3 = new Thread(SemaphoreExample::accessResource);

        t1.start();
        t2.start();
        t3.start();
    }

    private static void accessResource() {
        try {
            semaphore.acquire();  // Acquire a permit
            System.out.println(Thread.currentThread().getName() + " is accessing the resource.");
            Thread.sleep(1000);  // Simulate work
        } catch (InterruptedException e) {
            e.printStackTrace();
        } finally {
            semaphore.release();  // Release the permit
            System.out.println(Thread.currentThread().getName() + " released the resource.");
        }
    }
}

import java.util.LinkedList;

class MyHashMap<K, V> {

    // The initial capacity of the HashMap (number of buckets)
    private static final int INITIAL_CAPACITY = 16;
    private LinkedList<Node<K, V>>[] table;
    private int size = 0;


    // Constructor to initialize the table
    public MyHashMap() {
        table = new LinkedList[INITIAL_CAPACITY];
        for (int i = 0; i < INITIAL_CAPACITY; i++) {
            table[i] = new LinkedList
<>();
        }
    }

    // Node class to store key-value pairs
    private static class Node<K, V> {
        K key;
        V value;

        Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }

    // Hash function to calculate the index of the key
    private int getIndex(K key) {
        return Math.abs(key.hashCode()) % table.length;
    }

    // Put a key-value pair into the HashMap
    public void put(K key, V value) {
        int index = getIndex(key);
        LinkedList<Node<K, V>> bucket = table[index];

        // Check if the key already exists, and if so, update the value
        for (Node<K, V> node : bucket) {
            if (node.key.equals(key)) {
                node.value = value; // update value
                return;
            }
        }

        // Otherwise, add a new node to the bucket
        bucket.add(new Node<>(key, value));
        size++;

        // Resize if necessary (simplified version, no automatic resizing in this basic implementation)
        if (size >= table.length * 0.75) {
            resize();
        }
    }

    // Get the value associated with a key
    public V get(K key) {
        int index = getIndex(key);
        LinkedList<Node<K, V>> bucket = table[index];

        for (Node<K, V> node : bucket) {
            if (node.key.equals(key)) {
                return node.value;
            }
        }
        return null; // Key not found
    }

    // Remove the key-value pair associated with a key
    public void remove(K key) {
        int index = getIndex(key);
        LinkedList<Node<K, V>> bucket = table[index];

        for (Node<K, V> node : bucket) {
            if (node.key.equals(key)) {
                bucket.remove(node);
                size--;
                return;
            }
        }
    }

    // Check if a key exists in the map
    public boolean containsKey(K key) {
        int index = getIndex(key);
        LinkedList<Node<K, V>> bucket = table[index];

        for (Node<K, V> node : bucket) {
            if (node.key.equals(key)) {
                return true;
            }
        }
        return false;
    }

    // Resize the internal array when the load factor exceeds 0.75
    private void resize() {
        LinkedList<Node<K, V>>[] oldTable = table;
        table = new LinkedList[oldTable.length * 2];

        for (int i = 0; i < table.length; i++) {
            table[i] = new LinkedList<>();
        }

        for (LinkedList<Node<K, V>> bucket : oldTable) {
            for (Node<K, V> node : bucket) {
                put(node.key, node.value); // Rehash all entries
            }
        }
    }

    // Get the current size of the HashMap
    public int size() {
        return size;
    }
}

public class Main {
    public static void main(String[] args) {
        MyHashMap<String, Integer> map = new MyHashMap<>();

        // Put elements into the map
        map.put("apple", 1);
        map.put("banana", 2);
        map.put("cherry", 3);

        // Get elements
        System.out.println("apple: " + map.get("apple"));  // Output: 1
        System.out.println("banana: " + map.get("banana")); // Output: 2

        // Remove an element
        map.remove("banana");

        // Check existence of a key
        System.out.println("Contains key 'banana': " + map.containsKey("banana")); // Output: false

        // Check the size of the map
        System.out.println("Size of map: " + map.size());  // Output: 2
    }
}

