// Abstract handler class
public abstract class Handler
{
    private Handler _nextHandler;

    // Method to set the next handler in the chain
    public Handler SetNext(Handler nextHandler)
    {
        _nextHandler = nextHandler;
        return _nextHandler; // Return the next handler for fluent chaining
    }

    // Template method to handle the request
    public void Handle(string request)
    {
        if (CanHandle(request))
        {
            ProcessRequest(request);
        }
        else if (_nextHandler != null)
        {
            _nextHandler.Handle(request); // Pass the request to the next handler
        }
        else
        {
            Console.WriteLine($"No handler found for the request: {request}");
        }
    }

    // Abstract method to determine if the handler can process the request
    protected abstract bool CanHandle(string request);

    // Abstract method to process the request
    protected abstract void ProcessRequest(string request);
}

// Concrete handler 1
public class Handler1 : Handler
{
    protected override bool CanHandle(string request)
    {
        return request == "one";
    }

    protected override void ProcessRequest(string request)
    {
        Console.WriteLine("Handler1 is processing the request: " + request);
    }
}

