private boolean dfsCheckCycle(int node, boolean[] visited, boolean[] recStack) {
    visited[node] = true;
    recStack[node] = true;

    for (int neighbor : adjList.get(node)) {
        if (!visited[neighbor]) {
            if (dfsCheckCycle(neighbor, visited, recStack)) {
                return true;
            }
        } else if (recStack[neighbor]) {
            return true;
        }
    }

    recStack[node] = false;
    return false;
}

public boolean isCycle() {
    int[] inDegree = new int[vertices];
    for (int i = 0; i < vertices; i++) {
        for (int neighbor : adjList.get(i)) {
            inDegree[neighbor]++;
        }
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i < vertices; i++) {
        if (inDegree[i] == 0) {
            queue.add(i);
        }
    }

    int count = 0;
    while (!queue.isEmpty()) {
        int node = queue.poll();
        count++;

        for (int neighbor : adjList.get(node)) {
            inDegree[neighbor]--;
            if (inDegree[neighbor] == 0) {
                queue.add(neighbor);
            }
        }
    }

    return count != vertices;
}

