import java.sql.*;

public class JdbcPreparedStatementExample {
    public static void main(String[] args) {
        String url = "jdbc:mysql://localhost:3306/testdb"; // your DB
        String user = "root"; // your DB username
        String password = "password"; // your DB password

        try {
            // Load JDBC driver
            Class.forName("com.mysql.cj.jdbc.Driver");

            // Establish connection
            Connection connection = DriverManager.getConnection(url, user, password);

            // Insert data using PreparedStatement
            String insertSQL = "INSERT INTO users (username, email) VALUES (?, ?)";
            PreparedStatement insertStmt = connection.prepareStatement(insertSQL);
            insertStmt.setString(1, "john_doe");
            insertStmt.setString(2, "john@example.com");
            insertStmt.executeUpdate();

            // Query data using PreparedStatement
            String selectSQL = "SELECT * FROM users WHERE username = ?";
            PreparedStatement selectStmt = connection.prepareStatement(selectSQL);
            selectStmt.setString(1, "john_doe");
            ResultSet resultSet = selectStmt.executeQuery();

            // Display results
            while (resultSet.next()) {
                System.out.println("User ID: " + resultSet.getInt("id"));
                System.out.println("Username: " + resultSet.getString("username"));
                System.out.println("Email: " + resultSet.getString("email"));
            }

            // Clean up
            resultSet.close();
            insertStmt.close();
            selectStmt.close();
            connection.close();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

